code_snippets.parse_list:
async def parse_list(page):
    items = await page.query_selector_all('ul li')
    for item in items:
        detail_link = await item.query_selector_eval('a', 'a => a.href')
        title = await item.query_selector_eval('.title', 'el => el.innerText')
        yield {'title': title, 'detail_link': detail_link}
